steps.codeExample:
#[tokio::main]
async fn main() {
    let ouro = tokio::spawn(async { 50 });
    let xp = tokio::spawn(async { 120 });
    let (a, b) = tokio::join!(ouro, xp);
    println!("{:?} {:?}", a, b);
}

